args.Content:
import type { LifeCompanionView, LifeContent, LifeHabit, LifeHabitSuggestion, LifeSettings } from '../../../types/lifeReview';
import { CompanionPulseCard } from './CompanionPulseCard';
import { GoalBoard } from './GoalBoard';
import { RhythmCard } from './RhythmCard';
import { TodayReviewHero } from './TodayReviewHero';
import styles from './StatusTodayView.module.css';

interface StatusTodayViewProps {
  settings: LifeSettings;
  companion: LifeCompanionView | null;
  history: LifeContent[];
  habit: LifeHabit | null;
  suggestion: LifeHabitSuggestion | null;
  today: string;
  busy: boolean;
  generating: boolean;
  disabled: boolean;
  act: (work: () => Promise<unknown>, message: string) => Promise<void>;
  onOpenSettings?: (tab?: 'review' | 'context') => void;
}

/** 「今天」分段：左栏直出今日复盘，右栏集中展示陪伴节奏、个人目标与作息节律。 */
export function StatusTodayView({
  settings, companion, history, habit, suggestion, today, busy, generating, disabled, act, onOpenSettings,
}: StatusTodayViewProps) {
  return <div className={styles.layout} role="tabpanel" id="status-panel-today" aria-labelledby="status-tab-today">
    <div className={styles.primary}>
      <TodayReviewHero settings={settings} history={history} habit={habit} today={today}
        busy={busy} generating={generating} disabled={disabled} act={act} onOpenSettings={onOpenSettings} />
    </div>
    <div className={styles.secondary}>
      <CompanionPulseCard companion={companion} timezone={settings.timezone} busy={busy} act={act} />
      <GoalBoard />
      <RhythmCard habit={habit} suggestion={suggestion} cognition={companion?.cognition ?? null}
        busy={busy} disabled={disabled} act={act} />
    </div>
  </div>;
}

.layout { display: grid; grid-template-columns: minmax(0, 1.45fr) minmax(300px, 1fr); gap: 22px; align-items: start; }
.primary, .secondary { min-width: 0; display: flex; flex-direction: column; gap: 18px; }
@media (max-width: 900px) {
  .layout { grid-template-columns: minmax(0, 1fr); gap: 18px; }
}

import { useState } from 'react';
import { Brain, Clock, Compass, Heart, MessageCircleHeart, Pencil, RefreshCw } from 'lucide-react';
import { lifeReviewApi } from '../../../services/lifeReviewApi';
import type { LifeCompanionView, SaveLifeCognitionInput } from '../../../types/lifeReview';
import { formatDateTime, formatHour } from '../../../features/review/statusPresentation';
import { Button } from '../../common/Button';
import { Select } from '../../common/Select';
import { MemoryDocumentManager } from '../../memory/MemoryDocumentManager';
import { PersonalProfileSection } from '../../settings/PersonalProfileSection';
import { ReviewEmptyState } from '../ReviewEmptyState';
import { ReviewFormModal } from '../ReviewFormModal';
import styles from './StatusInsightView.module.css';

type CognitionDimensionKey = 'backgroundAndPreferences' | 'routineAndBusyHours' | 'activeFocusAndBlockers' | 'pendingHooksAndCuriosities';

const DIMENSIONS: readonly {
  key: CognitionDimensionKey;
  title: string;
  placeholder: string;
  fallback: string;
  icon: typeof Brain;
}[] = [
  { key: 'backgroundAndPreferences', title: '基本背景与性格喜好', fallback: '等待从日常对话与记录中自动学习…', placeholder: '例如：偏好简洁、直接给结论的中文交流', icon: Heart },
  { key: 'routineAndBusyHours', title: '作息规律与平时忙闲时段', fallback: '工作日白天通常在忙，晚间较常互动', placeholder: '例如：工作日 09:00—18:00 专心工作，晚间活跃', icon: Clock },
  { key: 'activeFocusAndBlockers', title: '近期主线大事与卡点', fallback: '等待从待办、学习与手记中自动提炼近期主线…', placeholder: '例如：正在推进某个项目或需要突破的难题', icon: Compass },
  { key: 'pendingHooksAndCuriosities', title: '上次未完话头与好奇点', fallback: '等待从最近聊天中捕捉待跟进话头与好奇提问…', placeholder: '例如：上次聊到但还没来得及继续的话题', icon: MessageCircleHeart },
];

const HOURS = Array.from({ length: 24 }, (_, idx) => ({ value: String(idx), label: formatHour(idx) }));

interface StatusInsightViewProps {
  companion: LifeCompanionView | null;
  timezone: string;
  busy: boolean;
  memorySummary: { active: number; total: number } | null;
  act: (work: () => Promise<unknown>, message: string) => Promise<void>;
}

/** 「认知」分段：对比展示 Agent 自动学习的四维系统性认知与用户主动维护的画像/经历来源。 */
export function StatusInsightView({ companion, timezone, busy, memorySummary, act }: StatusInsightViewProps) {
  const [editing, setEditing] = useState<CognitionDimensionKey | null>(null);
  const [draft, setDraft] = useState<SaveLifeCognitionInput | null>(null);
  const cognition = companion?.cognition ?? null;

  function openEdit(key: CognitionDimensionKey) {
    if (!cognition) return;
    setDraft({
      backgroundAndPreferences: cognition.backgroundAndPreferences,
      routineAndBusyHours: cognition.routineAndBusyHours,
      activeFocusAndBlockers: cognition.activeFocusAndBlockers,
      pendingHooksAndCuriosities: cognition.pendingHooksAndCuriosities,
      busyStartHour: cognition.busyStartHour,
      busyEndHour: cognition.busyEndHour,
    });
    setEditing(key);
  }

  const activeDim = DIMENSIONS.find(item => item.key === editing) ?? null;

  return <div className={styles.page} role="tabpanel" id="status-panel-insight" aria-labelledby="status-tab-insight">
    <section className={styles.block} aria-label="Agent 对你的系统性认知">
      <header className={styles.blockHeader}>
        <div>
          <h2><Brain size={16} aria-hidden="true" />Agent 学到的你</h2>
          <p>
            独立维护四维陪伴认知并在对话时按需参考，不会覆盖个人画像；最近更新：{formatDateTime(cognition?.updatedAt, timezone)}。
          </p>
        </div>
        {companion && (
          <Button size="sm" variant="outline" icon={<RefreshCw size={14} />} disabled={busy}
            onClick={() => void act(() => lifeReviewApi.learnCompanion(), '已从近期全量记录更新对你的系统性认知')}>
            立即学习更新
          </Button>
        )}
      </header>

      {!cognition ? (
        <div className={styles.emptyCard}>
          <ReviewEmptyState title="尚未获取到系统性认知" description="等待后台陪伴模块初始化完成后，这里会展示自动学习到的四个维度。" />
        </div>
      ) : (
        <div className={styles.grid}>
          {DIMENSIONS.map(dim => {
            const Icon = dim.icon;
            const text = cognition[dim.key];
            return <article key={dim.key} className={styles.dimCard}>
              <div className={styles.dimHeader}>
                <span className={styles.dimTitle}><Icon size={15} aria-hidden="true" />{dim.title}</span>
                <Button size="sm" variant="ghost" icon={<Pencil size={13} />} disabled={busy}
                  aria-label={`修改 ${dim.title}`} onClick={() => openEdit(dim.key)}>
                  修改
                </Button>
              </div>
              <p className={text ? styles.dimText : styles.dimFallback}>{text || dim.fallback}</p>
              {dim.key === 'routineAndBusyHours' && (
                <div className={styles.busyWindow}>
                  忙时免打扰窗口：{formatHour(cognition.busyStartHour)}—{formatHour(cognition.busyEndHour)}
                </div>
              )}
            </article>;
          })}
        </div>
      )}
    </section>

    <section className={styles.block} aria-label="由你直接维护的上下文">
      <header className={styles.blockHeader}>
        <div>
          <h2>你告诉 Agent 的</h2>
          <p>由你显式填写或授权登记，正文与详情仅在你点击打开弹窗时加载展示。</p>
        </div>
      </header>
      <div className={styles.tiles}>
        <PersonalProfileSection showMaintenanceToggle={false} variant="tile" />
        <MemoryDocumentManager variant="tile" sourceSummary={memorySummary} />
      </div>
    </section>

    <ReviewFormModal
      open={Boolean(activeDim && draft)}
      title={activeDim ? `修改 · ${activeDim.title}` : '修改系统性认知'}
      busy={busy}
      onClose={() => { setEditing(null); setDraft(null); }}
      footer={<>
        <Button size="sm" onClick={() => { setEditing(null); setDraft(null); }}>取消</Button>
        <Button size="sm" variant="primary" disabled={busy || !draft} onClick={() => draft && void act(async () => {
          await lifeReviewApi.saveCognition(draft);
          setEditing(null);
          setDraft(null);
        }, '系统性认知已保存')}>
          保存系统性认知
        </Button>
      </>}
    >
      {activeDim && draft && <div className={styles.modalForm}>
        <label className={styles.field}>
          <span>{activeDim.title}</span>
          <textarea
            className={styles.textarea}
            aria-label={activeDim.title}
            rows={4}
            value={draft[activeDim.key]}
            placeholder={activeDim.placeholder}
            disabled={busy}
            onChange={event => setDraft({ ...draft, [activeDim.key]: event.target.value })}
          />
        </label>
        {activeDim.key === 'routineAndBusyHours' && (
          <div className={styles.field}>
            <span>常规忙碌时段（忙时未回复将顺延至忙完后跟进）</span>
            <div className={styles.hours}>
              <Select aria-label="忙碌开始小时" value={String(draft.busyStartHour)} disabled={busy} options={HOURS}
                onChange={event => setDraft({ ...draft, busyStartHour: Number(event.target.value) })} />
              <span>至</span>
              <Select aria-label="忙碌结束小时" value={String(draft.busyEndHour)} disabled={busy} options={HOURS}
                onChange={event => setDraft({ ...draft, busyEndHour: Number(event.target.value) })} />
            </div>
          </div>
        )}
      </div>}
    </ReviewFormModal>
  </div>;
}

.page { display: flex; flex-direction: column; gap: 28px; }
.block { display: flex; flex-direction: column; gap: 14px; }
.blockHeader { display: flex; align-items: flex-start; justify-content: space-between; gap: 16px; flex-wrap: wrap; }
.blockHeader h2 { display: inline-flex; align-items: center; gap: 8px; margin: 0; color: var(--text-primary); font-size: 15px; font-weight: 600; }
.blockHeader p { margin: 4px 0 0; color: var(--text-secondary); font-size: 12px; line-height: 1.6; }
.emptyCard { border: 1px solid var(--border-subtle); border-radius: 12px; background: var(--bg-app); }
.grid, .tiles { display: grid; grid-template-columns: repeat(2, minmax(0, 1fr)); gap: 14px; }
.dimCard { min-width: 0; display: flex; flex-direction: column; gap: 10px; padding: 16px 18px; border: 1px solid var(--border-subtle); border-radius: 12px; background: var(--bg-app); }
.dimHeader { display: flex; align-items: center; justify-content: space-between; gap: 10px; }
.dimTitle { display: inline-flex; align-items: center; gap: 7px; color: var(--text-primary); font-size: 13px; font-weight: 600; }
.dimTitle svg { color: var(--text-secondary); flex: 0 0 auto; }
.dimText, .dimFallback { margin: 0; font-size: 13px; line-height: 1.7; white-space: pre-wrap; overflow-wrap: anywhere; }
.dimText { color: var(--text-primary); }
.dimFallback { color: var(--text-muted); }
.busyWindow { align-self: flex-start; padding: 3px 9px; border-radius: 999px; background: var(--bg-surface); color: var(--text-secondary); font-size: 11px; }
.modalForm { display: flex; flex-direction: column; gap: 14px; }
.field { display: flex; flex-direction: column; gap: 8px; font-size: 13px; font-weight: 500; color: var(--text-primary); }
.textarea { box-sizing: border-box; width: 100%; padding: 10px 12px; border: 1px solid var(--border-medium); border-radius: 10px; font: 400 13px/1.6 var(--font-sans); color: var(--text-primary); background: var(--bg-app); resize: vertical; }
.textarea:focus { outline: none; border-color: var(--border-focus); }
.hours { display: flex; align-items: center; gap: 8px; flex-wrap: wrap; color: var(--text-secondary); font-weight: 400; }
@media (max-width: 760px) {
  .grid, .tiles { grid-template-columns: minmax(0, 1fr); }
}

