import { useEffect, useState } from 'react';
import type { LifeContent } from '../../../types/lifeReview';
import { dayTitle, type ReviewDay } from '../../../features/review/statusPresentation';
import { Drawer } from '../../common/Drawer';
import { LifeContentCard } from '../LifeContentCard';
import { LifeReviewDetailsContent } from '../LifeReviewDetails';
import styles from './ReviewDayDrawer.module.css';

type DrawerView = 'content' | 'references' | 'version';

interface ReviewDayDrawerProps {
  reviewDay: ReviewDay | null;
  timezone: string;
  busy: boolean;
  authorized: boolean;
  feishu: boolean;
  onClose: () => void;
  act: (work: () => Promise<unknown>, message: string) => Promise<void>;
}

/** 按日复盘阅读抽屉：单层抽屉内切换版本与正文/参考记录/版本信息，避免多层抽屉叠加。 */
export function ReviewDayDrawer({ reviewDay, timezone, busy, authorized, feishu, onClose, act }: ReviewDayDrawerProps) {
  const [selectedId, setSelectedId] = useState<string>('');
  const [mode, setMode] = useState<DrawerView>('content');

  useEffect(() => {
    if (reviewDay) {
      setSelectedId(reviewDay.latest.id);
      setMode('content');
    }
  }, [reviewDay]);

  if (!reviewDay) return null;
  const current: LifeContent = reviewDay.versions.find(v => v.id === selectedId) ?? reviewDay.latest;

  return <Drawer
    open
    width={640}
    title={`${dayTitle(reviewDay.day)} · 复盘详情`}
    description={`${reviewDay.day} · 共 ${reviewDay.versions.length} 个不可变版本`}
    onClose={onClose}
  >
    <div className={styles.wrap}>
      {reviewDay.versions.length > 1 && (
        <div className={styles.versions} role="group" aria-label="切换版本">
          {reviewDay.versions.map((v, idx) => <button key={v.id} type="button"
            aria-pressed={current.id === v.id}
            onClick={() => setSelectedId(v.id)}>
            v{v.version}{idx === 0 ? '（最新）' : ''}
          </button>)}
        </div>
      )}

      <div className={styles.views} role="tablist" aria-label="复盘内容视角">
        {([
          ['content', '复盘正文'],
          ['references', '参考记录'],
          ['version', '版本信息'],
        ] as const).map(([key, label]) => <button key={key} type="button" role="tab"
          aria-selected={mode === key}
          onClick={() => setMode(key)}>{label}</button>)}
      </div>

      {mode === 'content' ? (
        <LifeContentCard key={current.id} className={styles.card} hideDetailButtons content={current}
          timezone={current.timezone || timezone} busy={busy} authorized={authorized} feishu={feishu} act={act} />
      ) : (
        <LifeReviewDetailsContent key={`${current.id}-${mode}`} content={current} timezone={current.timezone || timezone} mode={mode} />
      )}
    </div>
  </Drawer>;
}

.wrap { display: flex; flex-direction: column; gap: 14px; }
.versions, .views { display: flex; flex-wrap: wrap; gap: 6px; }
.versions button { min-height: 26px; padding: 0 10px; border: 1px solid var(--border-subtle); border-radius: 999px; background: var(--bg-app); color: var(--text-secondary); font: 500 11px var(--font-sans); cursor: pointer; }
.versions button[aria-pressed='true'] { border-color: #93c5fd; background: #eff6ff; color: #1d4ed8; font-weight: 600; }
.views { padding: 3px; border-radius: 9px; background: var(--bg-surface); align-self: flex-start; }
.views button { min-height: 28px; padding: 0 12px; border: 0; border-radius: 6px; background: transparent; color: var(--text-secondary); font: 500 12px var(--font-sans); cursor: pointer; }
.views button[aria-selected='true'] { background: var(--bg-app); color: var(--text-primary); font-weight: 600; box-shadow: 0 1px 3px #0f172a0f; }
.wrap .card { margin: 0; }

import { useState } from 'react';
import { Bell, ChevronRight, History } from 'lucide-react';
import { lifeReviewApi } from '../../../services/lifeReviewApi';
import type { LifeCandidate, LifeContent, LifeNudge, LifeSettings } from '../../../types/lifeReview';
import {
  buildOutreachTimeline, dayTitle, FEEDBACK_LABELS, formatDateTime, groupReviewDays,
  OUTREACH_FILTERS, REVIEW_STATE_LABELS, reviewExcerpt, type OutreachCategory, type ReviewDay,
} from '../../../features/review/statusPresentation';
import { Button } from '../../common/Button';
import { ReviewEmptyState } from '../ReviewEmptyState';
import { ReviewDayDrawer } from './ReviewDayDrawer';
import { StatusCard } from './StatusCard';
import styles from './StatusTimelineView.module.css';

interface StatusTimelineViewProps {
  settings: LifeSettings;
  history: LifeContent[];
  candidates: LifeCandidate[];
  nudges: LifeNudge[];
  archives: string[];
  busy: boolean;
  disabled: boolean;
  act: (work: () => Promise<unknown>, message: string) => Promise<void>;
}

/** 「足迹」分段：左侧按日复盘时间线，右侧合并主动问候、提醒与复盘候选并支持筛选与行内反馈。 */
export function StatusTimelineView({
  settings: s, history, candidates, nudges, archives, busy, disabled, act,
}: StatusTimelineViewProps) {
  const [selectedDay, setSelectedDay] = useState<string | null>(null);
  const [filter, setFilter] = useState<OutreachCategory | 'all'>('all');

  const days = groupReviewDays(history);
  const activeReviewDay: ReviewDay | null = selectedDay ? days.find(d => d.day === selectedDay) ?? null : null;
  const timeline = buildOutreachTimeline(nudges, candidates);
  const visibleOutreach = filter === 'all' ? timeline : timeline.filter(item => item.category === filter);

  const enabledRules = [
    s.idleCheckinDays ? `连续 ${s.idleCheckinDays} 天无互动问候` : '',
    s.weatherAlertEnabled ? '天气变化提醒' : '',
    s.expenseAlertEnabled ? '支出变化提醒' : '',
    s.serverAlertEnabled ? `服务器探针提醒（${s.serverProbeName || '应用服务器'}）` : '',
    s.mailAlertEnabled ? `重要邮件提醒（${s.imapHost || 'IMAP'}）` : '',
  ].filter(Boolean);

  return <div className={styles.layout} role="tabpanel" id="status-panel-timeline" aria-labelledby="status-tab-timeline">
    <StatusCard
      title="复盘时间线"
      icon={<History size={16} />}
      description={days.length > 0 ? `已记录 ${days.length} 天、共 ${history.length} 个版本；点击日期阅读正文与参考材料。` : '每日复盘生成后按归属日排列在这里。'}
    >
      {days.length === 0 ? (
        <ReviewEmptyState title="还没有生活复盘" description="在「今天」准备首份复盘后，每天的回顾和历史版本会保留在这里。" />
      ) : (
        <ul className={styles.dayList}>
          {days.map(day => <li key={day.day}>
            <button type="button" className={styles.dayItem} onClick={() => setSelectedDay(day.day)}>
              <div className={styles.dayTop}>
                <strong>{dayTitle(day.day)}</strong>
                <div className={styles.dayBadges}>
                  {day.versions.length > 1 && <span className={styles.tag}>{day.versions.length} 个版本</span>}
                  <span className={styles.state} data-state={day.latest.state}>{REVIEW_STATE_LABELS[day.latest.state] || day.latest.state}</span>
                  <ChevronRight size={14} aria-hidden="true" />
                </div>
              </div>
              <p className={styles.excerpt}>{reviewExcerpt(day.latest)}</p>
              <span className={styles.daySub}>{day.day} · 最新 v{day.latest.version}</span>
            </button>
          </li>)}
        </ul>
      )}
      {archives.length > 0 && (
        <div className={styles.archives}>
          {archives.map((a, i) => <details key={i}>
            <summary>重置前的只读外发副本 {i + 1}</summary>
            <p>{a}</p>
          </details>)}
        </div>
      )}
    </StatusCard>

    <StatusCard
      title="主动联系时间线"
      icon={<Bell size={16} />}
      description={enabledRules.length > 0 ? `已开启：${enabledRules.join('、')}（未回复不催促）` : '暂无已开启的提醒规则，可在复盘设置中按需开启。'}
    >
      <div className={styles.filters} role="group" aria-label="筛选主动联系记录">
        {OUTREACH_FILTERS.map(item => {
          const count = item.value === 'all' ? timeline.length : timeline.filter(entry => entry.category === item.value).length;
          return <button key={item.value} type="button" aria-pressed={filter === item.value} onClick={() => setFilter(item.value)}>
            {item.label} {count > 0 ? `· ${count}` : ''}
          </button>;
        })}
      </div>

      {visibleOutreach.length === 0 ? (
        <ReviewEmptyState
          title={timeline.length === 0 ? '暂无主动联系或候选记录' : '当前筛选下没有记录'}
          description="触发过问候、提醒或复盘候选后，时间、状态与你的反馈会集中显示在这里。"
        />
      ) : (
        <ul className={styles.outreachList}>
          {visibleOutreach.map(entry => <li key={entry.key} className={styles.outreachItem}>
            <div className={styles.outreachHead}>
              <strong>{entry.title}</strong>
              <span className={styles.tag}>{entry.stateLabel}</span>
            </div>
            <p className={styles.outreachText}>{entry.text}</p>
            <div className={styles.outreachFoot}>
              <span>{formatDateTime(entry.at, s.timezone)}{entry.feedback ? ` · 已反馈：${FEEDBACK_LABELS[entry.feedback] || entry.feedback}` : ''}</span>
              <div className={styles.outreachActions}>
                {entry.source === 'nudge' ? (
                  (['HELPFUL', 'NOT_NEEDED'] as const).map(decision => (
                    <Button key={decision} size="sm" variant="ghost" disabled={busy || entry.feedback === decision}
                      onClick={() => void act(() => lifeReviewApi.nudgeFeedback(entry.id, decision), '问候反馈已记录')}>
                      {decision === 'HELPFUL' ? '有帮助' : '暂不需要'}
                    </Button>
                  ))
                ) : (
                  (entry.state === 'PENDING' ? ['CANCEL'] : ['HELPFUL', 'NOT_RELEVANT']).map(decision => (
                    <Button key={decision} size="sm" variant="ghost" disabled={busy}
                      onClick={() => void act(() => lifeReviewApi.feedback(entry.id, decision), '反馈已记录')}>
                      {decision === 'CANCEL' ? '取消候选' : decision === 'HELPFUL' ? '有帮助' : '不相关'}
                    </Button>
                  ))
                )}
              </div>
            </div>
          </li>)}
        </ul>
      )}
    </StatusCard>

    <ReviewDayDrawer reviewDay={activeReviewDay} timezone={s.timezone} busy={busy} authorized={!disabled} feishu={s.feishu}
      onClose={() => setSelectedDay(null)} act={act} />
  </div>;
}

.layout { display: grid; grid-template-columns: minmax(0, 1.05fr) minmax(0, 1.25fr); gap: 22px; align-items: start; }
.dayList, .outreachList { display: flex; flex-direction: column; gap: 10px; margin: 0; padding: 0; list-style: none; }
.dayItem { box-sizing: border-box; width: 100%; display: flex; flex-direction: column; gap: 6px; padding: 13px 14px; border: 1px solid var(--border-subtle); border-radius: 10px; background: var(--bg-app); text-align: left; cursor: pointer; transition: border-color var(--transition-fast), background-color var(--transition-fast); }
.dayItem:hover { border-color: #93c5fd; background: #f8fbff; }
.dayItem:focus-visible { outline: 2px solid var(--accent-blue); outline-offset: 2px; }
.dayTop, .outreachHead { display: flex; align-items: center; justify-content: space-between; gap: 10px; }
.dayTop strong, .outreachHead strong { color: var(--text-primary); font-size: 13px; font-weight: 600; }
.dayBadges { display: inline-flex; align-items: center; gap: 6px; color: var(--text-muted); }
.tag, .state { padding: 2px 7px; border-radius: 6px; background: var(--bg-surface); color: var(--text-secondary); font-size: 11px; white-space: nowrap; }
.state[data-state='READY'] { background: #ecfdf5; color: #047857; }
.state[data-state='DEGRADED'], .state[data-state='UNKNOWN'] { background: #fff7ed; color: #9a3412; }
.excerpt { display: -webkit-box; -webkit-line-clamp: 2; -webkit-box-orient: vertical; overflow: hidden; margin: 0; color: var(--text-secondary); font-size: 12px; line-height: 1.6; }
.daySub { color: var(--text-muted); font-size: 11px; }
.archives { display: flex; flex-direction: column; gap: 8px; padding-top: 8px; border-top: 1px solid var(--border-subtle); font-size: 12px; color: var(--text-secondary); }
.archives p { white-space: pre-wrap; margin: 6px 0 0; padding: 10px; border-radius: 8px; background: var(--bg-surface); }
.filters { display: flex; flex-wrap: wrap; gap: 6px; }
.filters button { min-height: 26px; padding: 0 11px; border: 1px solid var(--border-subtle); border-radius: 999px; background: var(--bg-app); color: var(--text-secondary); font: 500 11px var(--font-sans); cursor: pointer; }
.filters button[aria-pressed='true'] { border-color: #93c5fd; background: #eff6ff; color: #1d4ed8; font-weight: 600; }
.outreachItem { display: flex; flex-direction: column; gap: 6px; padding: 12px 14px; border-radius: 10px; background: var(--bg-surface); }
.outreachText { margin: 0; color: var(--text-primary); font-size: 12px; line-height: 1.6; overflow-wrap: anywhere; }
.outreachFoot { display: flex; align-items: center; justify-content: space-between; gap: 10px; flex-wrap: wrap; color: var(--text-muted); font-size: 11px; }
.outreachActions { display: inline-flex; gap: 4px; }
@media (max-width: 960px) {
  .layout { grid-template-columns: minmax(0, 1fr); }
}
@media (prefers-reduced-motion: reduce) { .dayItem { transition: none; } }

