3: /**
4:  * 桌面端长期偏好统一入口。
5:  *
6:  * 权威来源是 `~/.butvan-agent/desktop/preferences.json`（与后端业务数据同寿命），
7:  * localStorage 仅作为同步读缓存与浏览器开发环境兜底。删除或重装应用、第三方
8:  * 卸载工具清理 `~/Library` 都不会再丢掉用户习惯。
9:  */
10: const cache = new Map<string, string>();
11: let initialized = false;
12: 
13: /** 旧版本只存在于 WebView localStorage 的偏好键，启动时一次性迁入文件。 */
14: const LEGACY_KEYS = [
15:   'butvan.featurePreferences',
16:   'butvan.calendarStickyNotes.expansion',
17:   'butvan.sidebarWidth',
18:   'butvan.studyWidgetPosition',
19:   'butvan.slashCommandPreferences',
20:   'butvan-record-summary-copy',
21: ] as const;
22: 
23: /**
24:  * 启动时预加载偏好文件，并把仅存在于 localStorage 的旧值写回文件。
25:  * 必须在渲染应用前完成，保证同步读取接口已有数据。
26:  */
27: export async function initDesktopPreferences(): Promise<void> {
28:   if (initialized) return;
29:   initialized = true;
30:   if (!isTauri()) return;
31:   try {
32:     const stored = await invoke<Record<string, string>>('load_desktop_preferences');
33:     Object.entries(stored).forEach(([key, value]) => cache.set(key, value));
34:   } catch (error) {
35:     console.warn('桌面偏好读取失败，暂用本机缓存', error);
36:   }
37:   await migrateLegacyPreferences();
38: }
39: 
40: async function migrateLegacyPreferences(): Promise<void> {
41:   for (const key of LEGACY_KEYS) {
42:     if (cache.has(key)) continue;
43:     let legacy: string | null = null;
44:     try {
45:       legacy = localStorage.getItem(key);
46:     } catch {
47:       legacy = null;
48:     }
49:     if (legacy === null) continue;
50:     cache.set(key, legacy);
51:     try {
52:       await invoke('save_desktop_preference', { key, value: legacy });
53:     } catch (error) {
54:       console.warn('旧偏好迁移失败，将在下次写入时重试', key, error);
55:     }
56:   }
57: }
58: 
59: /** 同步读取偏好：文件缓存优先，其次旧 localStorage 数据。 */
60: export function readPreference(key: string): string | null {
61:   const cached = cache.get(key);
62:   if (cached !== undefined) return cached;
63:   try {
64:     return localStorage.getItem(key);
65:   } catch {
66:     return null;
67:   }
68: }
69: 
70: /** 写入偏好：localStorage 保持同步缓存，文件为权威存储，失败只记录日志。 */
71: export function writePreference(key: string, value: string): void {
72:   cache.set(key, value);
73:   try {
74:     localStorage.setItem(key, value);
75:   } catch {
76:     // localStorage 只是缓存，写入失败不影响文件持久化。
77:   }
78:   if (!isTauri()) return;
79:   void invoke('save_desktop_preference', { key, value }).catch((error) => {
80:     console.warn('桌面偏好保存失败', key, error);
81:   });
82: }
83: 
84: /** 等待权威存储成功后才更新缓存，供需要明确失败反馈的偏好及缩略图上传使用。 */
85: export async function writePreferenceConfirmed(key: string, value: string): Promise<void> {
86:   if (isTauri()) {
87:     await invoke('save_desktop_preference', { key, value });
88:     cache.set(key, value);
89:     try { localStorage.setItem(key, value); } catch { /* 桌面文件已保存，浏览器缓存失败不影响结果。 */ }
90:     return;
91:   }
92:   localStorage.setItem(key, value);
93:   cache.set(key, value);
94: }

