/** 去掉正文中与卡片标题完全重复的 `【标题】` 前缀。 */
export function cleanOutreachText(text: string, title: string): string {
  const prefix = `【${title}】`;
  if (text.startsWith(prefix)) return text.slice(prefix.length).trim();
  return text.replace(/^【[^】]{2,14}提醒】\s*/, '');
}

