.pulse[data-tone='wait'] .dot { background: #f59e0b; box-shadow: 0 0 0 3px #fef3c7; }
.metaLine { display: flex; flex-wrap: wrap; align-items: center; gap: 4px 6px; margin: 0; color: var(--text-secondary); font-size: 11px; line-height: 1.5; }
.actions { display: flex; flex-wrap: wrap; gap: 6px; }
@media (prefers-reduced-motion: no-preference) { .pulse[data-tone='on'] .dot { animation: breathe 2.4s ease-in-out infinite; } }
@keyframes breathe { 50% { box-shadow: 0 0 0 5px #d1fae5; } }

