23: /** 按后端配置时区计算归属日，避免用本机日期推断。 */
24: export function zonedDay(timezone: string, now = new Date()): string {
25:   let parts: Intl.DateTimeFormatPart[];
26:   try {
27:     parts = new Intl.DateTimeFormat('en', { timeZone: timezone || 'Asia/Shanghai', year: 'numeric', month: '2-digit', day: '2-digit' }).formatToParts(now);
28:   } catch {
29:     parts = new Intl.DateTimeFormat('en', { timeZone: 'Asia/Shanghai', year: 'numeric', month: '2-digit', day: '2-digit' }).formatToParts(now);
30:   }
31:   return ['year', 'month', 'day'].map(type => parts.find(part => part.type === type)?.value || '').join('-');
32: }
33: 
34: export function zonedHour(timezone: string, now = new Date()): number {
35:   try {
36:     const value = new Intl.DateTimeFormat('en', { timeZone: timezone || 'Asia/Shanghai', hour: 'numeric', hourCycle: 'h23' }).format(now);
37:     const hour = Number(value);
38:     return Number.isFinite(hour) ? hour % 24 : now.getHours();
39:   } catch {
40:     return now.getHours();
41:   }
42: }
