44: export function greetingFor(hour: number): string {
45:   if (hour < 5) return '夜深了';
46:   if (hour < 11) return '早上好';
47:   if (hour < 14) return '中午好';
48:   if (hour < 18) return '下午好';
49:   return '晚上好';
50: }
