52: /** 中文日期标题，例如「11月14日 周五」；无效日期返回原值。 */
53: export function dayTitle(day: string): string {
54:   const [y, m, d] = day.split('-').map(Number);
55:   if (!y || !m || !d) return day;
56:   const week = ['周日', '周一', '周二', '周三', '周四', '周五', '周六'][new Date(Date.UTC(y, m - 1, d)).getUTCDay()];
57:   return `${m}月${d}日 ${week}`;
58: }
