4: /** Java ZonedDateTime 附带的区域名称不属于浏览器日期语法，保留原偏移后转换。 */
5: export function lifeReviewTime(value: string, timezone: string): string {
6:   if (!value) return '时间未记录';
7:   if (/^\d{4}-\d{2}-\d{2}$/.test(value)) return `${value}（归属日）`;
8:   const date = new Date(value.replace(/\[[^\]]+\]$/, '').replace(/(\.\d{3})\d+/, '$1'));
9:   if (!Number.isFinite(date.getTime())) return '时间未记录';
10:   try { return date.toLocaleString('zh-CN', { timeZone: timezone, hour12: false }); }
11:   catch { return '时区不可用'; }
12: }
