17: /** 按来源而非内部编号分类；未知来源独立保留，避免静默丢失材料。 */
18: export function lifeReferenceGroups(content: LifeContent): ReferenceGroup[] {
19:   const groups: ReferenceGroup[] = [
20:     { key: 'CHAT', title: '聊天', entries: [] },
21:     { key: 'HISTORICAL_MEMORY', title: '关联往期经历', entries: [] },
22:     { key: 'JOURNAL', title: '每日手记', entries: [] },
23:     { key: 'PERSONAL', title: '目标与反馈', entries: [] },
24:     { key: 'SUPPLEMENT', title: '补充经历', entries: [] },
25:     { key: 'FINANCE', title: '财务', entries: [] },
26:     { key: 'STUDY', title: '学习', entries: [] },
27:     { key: 'TODO', title: '待办', entries: [] },
28:     { key: 'OTHER', title: '其他材料', entries: [] },
29:   ];
30:   const add = (key: string, entry: ReferenceEntry) => (groups.find(g => g.key === key) || groups[8]).entries.push(entry);
31:   for (const material of content.materials) {
32:     const key = ['USER_GOAL', 'USER_FEEDBACK'].includes(material.kind) ? 'PERSONAL' : material.kind;
33:     add(key, { id: material.id, text: material.text, time: material.occurredAt, truncated: material.truncated });
34:   }
35:   for (const fact of content.facts || []) {
36:     add(fact.domain, { id: fact.id, text: lifeFactLabel(fact), time: fact.period, truncated: false });
37:   }
