.feedbackDone { color: var(--text-muted); }
.moreBtn { align-self: flex-start; padding: 5px 10px; border: 1px solid var(--border-subtle); border-radius: 999px; background: var(--bg-app); color: var(--text-secondary); font: 500 11px var(--font-sans); cursor: pointer; transition: background-color var(--transition-fast); }
.moreBtn:hover { background: var(--bg-surface); color: var(--text-primary); }
